package ru.neverland.townydistricts;
import java.util.*;
import ru.neverland.townydistricts.model.*;
import ru.neverland.townydistricts.config.AssessmentSettings;
import static ru.neverland.townydistricts.model.DistrictAssessment.*;
public final class DistrictAssessmentSmoke {
    static int checks;static UUID W=UUID.randomUUID(),T=UUID.randomUUID();
    static Cell cell(int x,int z){return new Cell(W,x,z);}static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
    interface Work{void run()throws Exception;}static void denied(Work work,String why)throws Exception{try{work.run();}catch(Exception expected){check(true,why);return;}throw new AssertionError(why);}
    static DistrictRules.Building b(String id,int x,int level){return new DistrictRules.Building(id,W,x*16,0,x*16+15,15,level,1);}
    static Input input(District d,List<DistrictRules.Building> buildings,Set<Cell> owned,Cell home,boolean available,Settings settings){return new Input(List.of(d),buildings,Map.of("residential_quarter",DistrictType.RESIDENTIAL,"forge",DistrictType.INDUSTRIAL,"park",DistrictType.RESIDENTIAL),owned,Set.of(W),home,16,available,settings);}
    public static void main(String[] args)throws Exception{
        var owned=new HashSet<Cell>();for(int i=0;i<7;i++)owned.add(cell(i,0));owned.add(cell(10,0));var d=new District(T,"homes","Жильё",DistrictType.RESIDENTIAL,Set.of(cell(3,0),cell(4,0)));var needs=new Settings(3,Map.of(DistrictType.RESIDENTIAL,List.of(new Need("medical","Медицина",Set.of("infirmary")),new Need("water","Вода",Set.of("aqueduct","reservoir")))));
        var buildings=List.of(b("residential_quarter",3,1),b("forge",4,1),b("park",3,0),b("custom",4,1),b("infirmary",1,1),new DistrictRules.Building("warehouse",W,79,0,80,15,1,1));var in=input(d,buildings,owned,cell(0,0),true,needs);var report=DistrictAssessment.calculate(in);var row=report.rows().get("homes");
        check(report.homeKnown()&&report.reached()==7&&row.connected()==2&&row.distance()==3,"home graph reaches adjacent claims but not remote outpost");check(row.matching()==1&&row.other()==1&&row.unfinished()==1&&row.crossing()==1&&row.unknownBuildings()==1,"profile counts matching, other, unfinished, crossing and unknown independently");check(row.services().get(0).served()==2&&row.services().get(0).sources().equals(Set.of("infirmary")),"service range includes exact outer boundary and identifies nearest genuine source");check(row.services().get(1).known()&&row.services().get(1).served()==0,"known missing service is explicitly zero");
        var firstLevel=new DistrictRules.Building("residential_quarter",W,48,0,63,15,1,5);check(DistrictAssessment.calculate(input(d,List.of(firstLevel),owned,cell(0,0),true,needs)).rows().get("homes").matching()==1,"existing completed level I counts as a building without requiring the future level V");
        check(report.assignments().get("residential_quarter").equals("homes")&&!report.assignments().containsKey("warehouse"),"physical assignment includes only fully owned district footprints and excludes crossings");
        var rangeTwo=new Settings(2,needs.needs());check(DistrictAssessment.calculate(input(d,buildings,owned,cell(0,0),true,rangeTwo)).rows().get("homes").services().get(0).served()==1,"radius does not leak beyond configured range");
        var unavailable=DistrictAssessment.calculate(input(d,buildings,owned,cell(0,0),false,needs)).rows().get("homes");check(!unavailable.buildingsAvailable()&&unavailable.services().stream().noneMatch(Coverage::known),"unavailable building provider is never reported as a known missing service");
        var noHome=DistrictAssessment.calculate(input(d,buildings,owned,null,true,needs));check(!noHome.homeKnown()&&noHome.rows().get("homes").distance()==-1,"unknown home retains explicit unknown connectivity");
        var gap=new HashSet<>(owned);gap.remove(cell(2,0));var supplied=new ArrayList<>(buildings);supplied.add(b("aqueduct",6,1));var broken=DistrictAssessment.calculate(input(d,supplied,gap,cell(0,0),true,needs)).rows().get("homes");check(broken.connected()==0&&broken.services().get(0).served()==0&&broken.services().get(1).served()==2,"claim gap breaks centre and remote service path while preserving local outpost service");
        var diagonal=new District(T,"diagonal","Диагональ",DistrictType.RESIDENTIAL,Set.of(cell(1,1)));check(DistrictAssessment.calculate(input(diagonal,List.of(),Set.of(cell(0,0),cell(1,1)),cell(0,0),true,needs)).rows().get("diagonal").connected()==0,"diagonal adjacency is not a route");
        var foreignWorld=UUID.randomUUID();var otherWorld=new DistrictRules.Building("infirmary",foreignWorld,16,0,31,15,1,1);check(DistrictAssessment.calculate(input(d,List.of(otherWorld),owned,cell(0,0),true,needs)).rows().get("homes").services().get(0).served()==0,"services never cross worlds");
        var unloaded=new Input(List.of(d),buildings,in.types(),owned,Set.of(),cell(0,0),16,true,needs);check(!DistrictAssessment.calculate(unloaded).rows().get("homes").worldAvailable()&&DistrictAssessment.calculate(unloaded).rows().get("homes").services().stream().noneMatch(Coverage::known),"unloaded world remains explicitly unknown");
        var negative=new District(T,"negative","Запад",DistrictType.RESIDENTIAL,Set.of(cell(-1,0)));var negativeBuilding=new DistrictRules.Building("residential_quarter",W,-16,0,-1,15,1,1);check(DistrictAssessment.calculate(input(negative,List.of(negativeBuilding),Set.of(cell(-1,0),cell(0,0)),cell(0,0),true,needs)).rows().get("negative").matching()==1,"negative block coordinates use floor division");
        var narrow=new District(T,"narrow","Узкий",DistrictType.RESIDENTIAL,Set.of(cell(3,0)));var crossing=new DistrictRules.Building("residential_quarter",W,63,0,64,15,1,1);var crossingRow=DistrictAssessment.calculate(input(narrow,List.of(crossing),owned,cell(0,0),true,needs)).rows().get("narrow");check(crossingRow.crossing()==1&&crossingRow.matching()==0,"boundary-crossing footprint cannot become a fully matching building");
        var oneLost=new HashSet<>(owned);oneLost.remove(cell(4,0));var lost=DistrictAssessment.calculate(input(d,List.of(b("forge",4,1)),oneLost,cell(0,0),true,needs)).rows().get("homes");check(lost.owned()==1&&lost.unknownBuildings()==1&&lost.other()==0,"lost land never contributes a verified building profile");
        var extremes=new District(T,"extreme","Граница",DistrictType.RESIDENTIAL,Set.of(cell(Integer.MIN_VALUE,0)));check(DistrictAssessment.calculate(input(extremes,List.of(),Set.of(cell(Integer.MIN_VALUE,0),cell(Integer.MAX_VALUE,0)),cell(Integer.MAX_VALUE,0),true,needs)).rows().get("extreme").connected()==0,"integer coordinate overflow cannot wrap a route around the world");
        denied(()->DistrictAssessment.calculate(input(d,List.of(b("forge",4,1),b("forge",3,1)),owned,cell(0,0),true,needs)),"duplicate footprint ID rejected");denied(()->DistrictAssessment.calculate(input(d,List.of(new DistrictRules.Building("bad",W,0,0,Integer.MAX_VALUE,0,1,1)),owned,cell(0,0),true,needs)),"unbounded footprint rejected instead of silently becoming absent");
        denied(()->new Settings(65,Map.of()),"service radius bounded");denied(()->new Need("bad","Bad",Set.of()),"empty service alternative list rejected");denied(()->report.rows().clear(),"assessment output immutable");denied(()->in.claimed().clear(),"captured claims immutable");
        var yaml=new org.bukkit.configuration.file.YamlConfiguration();check(AssessmentSettings.load(yaml).needs().size()==7,"old configurations receive seven default service groups");yaml.set("assessment.service-range-cells",-1);denied(()->AssessmentSettings.load(yaml),"invalid range not silently coerced");yaml.set("assessment.service-range-cells",8);yaml.set("assessment.services","broken");denied(()->AssessmentSettings.load(yaml),"malformed optional services not silently replaced by defaults");
        var random=new Random(52);for(int i=0;i<1000;i++){var shuffled=new ArrayList<>(buildings);Collections.shuffle(shuffled,random);if(!DistrictAssessment.calculate(input(d,shuffled,owned,cell(0,0),true,needs)).equals(report))throw new AssertionError("order-dependent assessment");}check(true,"1000 reordered source snapshots retain exactly the same report");
        System.out.println("DistrictAssessmentSmoke PASS "+checks+" checks and 1000 source permutations");
    }
}
